# Generate a batch of encoder configs/inputs varying patterns and transform depth/QP to see if we can avoid the unrelated intra bug and reach SAO.
from pathlib import Path
import itertools, os, re, textwrap
root=Path('/workspace')
# load original config lines
orig = Path('/workspace/repo-vul/src-vul/libhevc/test/encoder/vid_enc_cfg.txt').read_text(errors='ignore').splitlines()

def write_cfg(path, input_path, output_path, W,H, frames=1, qp=32, qpres=5, depthI=1, depthNI=3, bitrate=200000, rc=3, cores=1, deblock=0, entropy=0, temporal=0, gop=0):
    repl = {
        '--input':str(input_path), '--output':str(output_path), '--num_frames_to_encode':str(frames),
        '--src_width':str(W), '--src_height':str(H), '--input_chroma_format':'11',
        '--tgt_bitrate':str(bitrate), '--frame_qp':str(qp), '--quality_preset':str(qpres),
        '--num_cores':str(cores), '--rate_control_mode':str(rc), '--rc_look_ahead_pics':'0',
        '--max_temporal_layers':str(temporal), '--sei_enable_flags':'0', '--vui_enable':'0',
        '--log_dump_level':'0', '--max_tr_tree_depth_I':str(depthI), '--max_tr_tree_depth_nI':str(depthNI),
        '--deblocking_type':str(deblock), '--enable_entropy_sync':str(entropy),
        '--max_closed_gop_period':str(gop), '--min_closed_gop_period':'0', '--max_cra_open_gop_period':'0', '--max_i_open_gop_period':'0',
        '--cu_level_rc':'0', '--sps_at_cdr_enable':'0',
    }
    new=[]; seen=set()
    for line in orig:
        stripped=line.strip()
        if stripped.startswith('--'):
            key=stripped.split()[0]
            if key in repl:
                new.append(f'{key:<35} {repl[key]}')
                seen.add(key)
            else:
                # Keep rest, but some older input_chroma_format mismatch overwritten above
                new.append(line)
        else:
            new.append(line)
    for k,v in repl.items():
        if k not in seen:
            new.append(f'{k:<35} {v}')
    Path(path).write_text('\n'.join(new)+'\n')

def make_yuv(path,W,H,frames,pattern):
    data=bytearray()
    for f in range(frames):
        # luma
        for y in range(H):
            for x in range(W):
                if pattern=='zero': v=128
                elif pattern=='grad': v=(x*2+y*3+f*7)&255
                elif pattern=='checker': v=32 if ((x//16+y//16+f)&1)==0 else 224
                elif pattern=='edge': v=32 if x < W//2 else 224
                elif pattern=='stripes': v=(32 if ((x//8+f)&1)==0 else 224)
                elif pattern=='smooth_edge': v=max(0,min(255,128+(x-W//2)*4))
                elif pattern=='noise_low': v=(128 + ((x*17+y*31+f*43)&31)-16)&255
                else: v=128
                data.append(v)
        # chroma U,V planes, neutral or mild
        for plane in range(2):
            for y in range(H//2):
                for x in range(W//2):
                    if pattern in ['zero','edge','smooth_edge']:
                        v=128
                    elif pattern=='checker':
                        v=96 if ((x//8+y//8+plane+f)&1)==0 else 160
                    elif pattern=='stripes':
                        v=112 if ((y//4+plane+f)&1)==0 else 144
                    elif pattern=='grad':
                        v=(128+x*2+y*3+plane*20+f*5)&255
                    elif pattern=='noise_low':
                        v=(128+((x*7+y*11+plane*13+f*17)&15)-8)&255
                    else: v=128
                    data.append(v)
    Path(path).write_bytes(data)

batch_dir=Path('/workspace/enc_batch')
if batch_dir.exists():
    import shutil; shutil.rmtree(batch_dir)
batch_dir.mkdir()
configs=[]
