patterns=['zero','edge','checker','stripes','smooth_edge','grad','noise_low']
# use 256x128 and 128x128 maybe min width is 240 so 256 only.
idx=0
for frames in [1,2]:
  for pattern in patterns:
    for qp in [22,32,42,50]:
      for depthI in [1,2,3]:
        # for frames=2 use pattern varied over frames; gop no closed? max_i open 0 maybe all IDR? Need P frames if max_i_open maybe 60, gop cra 60.
        W,H=256,128
        idx+=1
        stem=f'case_{idx:03d}_{pattern}_f{frames}_qp{qp}_d{depthI}'
        inp=batch_dir/(stem+'.yuv'); out=batch_dir/(stem+'.265'); cfg=batch_dir/(stem+'.cfg')
        make_yuv(inp,W,H,frames,pattern)
        # For frames=2 allow P frame: max_cra_open_gop_period 60; max_i_open_gop_period 0? original max_i=60. Use repl below maybe set gop? not enough. We'll leave max_i_open_gop=60 by custom manual after?
        write_cfg(cfg, inp,out,W,H,frames=frames,qp=qp,qpres=5,depthI=depthI,depthNI=3,bitrate=300000,rc=3,cores=1,temporal=0)
        # modify config for frames=2 to set open gop defaults maybe: set max_cra_open_gop_period 60/max_i_open_gop_period 60, max_closed=0
