from pathlib import Path
import shutil, itertools, os, re
batch_dir=Path('/workspace/sao_batch')
if batch_dir.exists():
    shutil.rmtree(batch_dir)
batch_dir.mkdir()
orig_cfg_lines = Path('/workspace/repo-vul/src-vul/libhevc/test/encoder/vid_enc_cfg.txt').read_text(errors='ignore').splitlines()

def make_yuv(path,W,H,frames,pattern):
    data=bytearray()
    for f in range(frames):
        for y in range(H):
            for x in range(W):
                if pattern=='zero': v=128
                elif pattern=='flat64': v=64
                elif pattern=='edge': v=32 if x < W//2 else 224
                elif pattern=='checker8': v=32 if ((x//8+y//8+f)&1)==0 else 224
                elif pattern=='checker16': v=32 if ((x//16+y//16+f)&1)==0 else 224
                elif pattern=='stripes': v=32 if ((x//8+f)&1)==0 else 224
                elif pattern=='grad': v=(x*2+y*3+f*11)&255
                elif pattern=='smooth': v=max(0,min(255,128+(x-W//2)*2+(y-H//2)))
                elif pattern=='noise_low': v=(128 + ((x*17+y*31+f*43)&31)-16)&255
                elif pattern=='sao_diag': v=(20 if ((x+y)//16)&1 else 235)
                else: v=128
                data.append(v)
        for plane in range(2):
            for y in range(H//2):
                for x in range(W//2):
                    if pattern in ['zero','flat64','edge','smooth']:
                        v=128
                    elif pattern.startswith('checker'):
                        v=96 if ((x//8+y//8+plane+f)&1)==0 else 160
                    elif pattern=='stripes':
                        v=112 if ((y//4+plane+f)&1)==0 else 144
                    elif pattern=='grad':
                        v=(128+x*2+y*3+plane*20+f*5)&255
                    elif pattern=='noise_low':
                        v=(128+((x*7+y*11+plane*13+f*17)&15)-8)&255
                    elif pattern=='sao_diag':
                        v=80 if (((x+y)//8+plane)&1) else 176
                    else: v=128
                    data.append(v)
    Path(path).write_bytes(data)

def write_cfg(path, input_path, output_path, W,H, frames=1, qp=32, qpres=3, depthI=1, depthNI=3, bitrate=400000, rc=3, cores=1, deblock=0, entropy=0, temporal=0, gop_open=False):
    repl = {
        '--input':str(input_path), '--output':str(output_path), '--num_frames_to_encode':str(frames),
        '--src_width':str(W), '--src_height':str(H), '--input_chroma_format':'11',
        '--tgt_bitrate':str(bitrate), '--frame_qp':str(qp), '--quality_preset':str(qpres),
        '--num_cores':str(cores), '--rate_control_mode':str(rc), '--rc_look_ahead_pics':'0',
        '--max_temporal_layers':str(temporal), '--sei_enable_flags':'0', '--vui_enable':'0',
        '--log_dump_level':'0', '--max_tr_tree_depth_I':str(depthI), '--max_tr_tree_depth_nI':str(depthNI),
        '--deblocking_type':str(deblock), '--enable_entropy_sync':str(entropy), '--cu_level_rc':'0',
        '--sps_at_cdr_enable':'0',
        '--max_closed_gop_period':'0', '--min_closed_gop_period':'0',
        '--max_cra_open_gop_period':('60' if gop_open else '0'),
        '--max_i_open_gop_period':('60' if gop_open else '0'),
    }
    out=[]; seen=set()
    for line in orig_cfg_lines:
        stripped=line.strip()
        if stripped.startswith('--'):
            key=stripped.split()[0]
            if key in repl:
                out.append(f'{key:<35} {repl[key]}')
                seen.add(key)
            else:
                out.append(line)
        else:
            out.append(line)
    for k,v in repl.items():
        if k not in seen: out.append(f'{k:<35} {v}')
    Path(path).write_text('\n'.join(out)+'\n')

